INSERT INTO zinas (virsraksts, teksts, kategorija, izveidots, publicets) VALUES
('6. diena — mūsu mājvieta: viesu nams "Mežupes"',
'Sestajā dienā gribas pastāstīt par mūsu mājvietu — viesu namu "Mežupes".\n\nTā ir klusa lauku sēta Salacgrīvas pusē, meža ielokā, tikai nelielu gabalu no jūras. Sētas vidū slejas liela guļbaļķu māja ar skaistu niedru jumtu, bet mēs dzīvojam mazā pirts mājiņā turpat blakus — mājīgā guļbaļķu namiņā ar pašu pirti, tā ka silts gars ir tepat aiz durvīm. Ap māju zaļš mauriņš, dārzs un terase, kur vakaros var klausīties, kā čab priedes. Un nosaukums "Mežupes" — meža upe — nav nejaušs: gar sētu tek strauts, un pie nelielā aizsprosta ūdens gāžas lejup un skaļi šalc.\n\nMums, ceļotājiem ar diviem suņiem, šī vieta ir īsta atradums: dzīvnieki te gaidīti, un apkārt pietiek vietas, kur izskrieties. Saimnieki sirsnīgi, un arī viņiem pašiem ir suns — tā ka mūsējie uzreiz jutās kā savējie.\n\nRīti sākas ar kafiju, vakari — pirtī un pie uguns. Labāku bāzi rudens ceļojumam Vidzemes krastā grūti iedomāties.\n\n⸻\n\nKuudentena päivänä haluan kertoa majapaikastamme — vierasmaja "Mežupes".\n\nSe on hiljainen maalaispiha Salacgrīvan suunnalla, metsän sylissä, vain lyhyen matkan päässä merestä. Pihan keskellä kohoaa iso hirsitalo kauniin ruokokaton alla, mutta me majoitumme aivan sen vieressä pienessä saunamökissä — kodikkaassa hirsimökissä, jossa on oma sauna, joten lämmin löyly on aivan oven takana. Ympärillä vihreä nurmi, puutarha ja terassi, jolla iltaisin voi kuunnella mäntyjen huminaa. Ja nimi "Mežupes" — metsäjoki — ei ole sattumaa: pihan vierestä virtaa puro, ja pienen padon kohdalla vesi putoaa alas kohisten ja vaahdoten.\n\nMeille, kahden koiran kanssa matkaaville, paikka on todellinen löytö: eläimet ovat tervetulleita, ja ympärillä on tilaa juosta. Isäntäväki on sydämellistä, ja heilläkin on oma koira — niinpä meidän koiramme tunsivat olonsa heti kotoisaksi.\n\nAamut alkavat kahvilla, illat saunassa ja takan ääressä. Parempaa tukikohtaa syksyiselle Vidzemen rannikon matkalle on vaikea kuvitella.',
'celojums',
'2026-10-22 09:00:00',
1);
